{"command":"cat > /tmp/probe.py <<'PY'
import subprocess, time, os, sys, signal, socket, urllib.request, urllib.error

def free_port():
    import socket
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p

def start(args, cwd="/tmp/probe/root", env=None, port=None):
    if port is None: port=free_port()
    cmd=["/tmp/orig_exec"]+args
    # replace placeholder PORT
    cmd=[str(port) if x=="PORT" else x for x in cmd]
    e=dict(os.environ); 
    if env: e.update(env)
    proc=subprocess.Popen(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=e, text=True)
    # wait
    for i in range(50):
        time.sleep(0.1)
        try:
            s=socket.create_connection(('127.0.0.1',port),timeout=0.5); s.close(); break
        except Exception:
            if proc.poll() is not None: break
    return proc, port

def get(port, path, headers=None, method='GET', data=None):
    import http.client
    c=http.client.HTTPConnection('127.0.0.1',port,timeout=5)
    c.request(method, path, body=data, headers=headers or {})
    try:
        r=c.getresponse(); body=r.read(); hd=dict(r.getheaders()); return r.status, hd, body
    finally: c.close()

def stop(proc):
    if proc.poll() is None:
        proc.terminate()
        try: proc.wait(timeout=3)
        except: proc.kill(); proc.wait()
    out=""
    try: out=proc.stdout.read() if proc.stdout else ""
    except: pass
    return out
PY
