        if not re.fullmatch(r'[+-]?\d+', val or ""):
            _invalid_value(spec, val, "invalid digit found in string")
        try:
            iv = int(val)
        except Exception:
            _invalid_value(spec, val, "number too large to fit in target type")
        if abs(iv) > 9223372036854775807:
            _invalid_value(spec, val, "number too large to fit in target type")
        if iv < 0 or iv > 65535:
            _invalid_value(spec, val, "%d is not in 0..=65535" % iv)
        return iv
    if k == "usize":
        if val == "":
            _invalid_value(spec, val, "cannot parse integer from empty string")
        if not re.fullmatch(r'\d+', val or ""):
            _invalid_value(spec, val, "invalid digit found in string")
        iv = int(val)
        if iv > 18446744073709551615:
            _invalid_value(spec, val, "number too large to fit in target type")
        return iv
    if k == "chmod":
        if val == "":
            _invalid_value(spec, val, "cannot parse integer from empty string")
        if not re.fullmatch(r'\+?[0-7]+', val or ""):
            _invalid_value(spec, val, "invalid digit found in string")
        iv = int(val, 8)
        if iv > 4294967295:
            _invalid_value(spec, val, "number too large to fit in target type")
        return iv
    if k == "ip":
        try:
            return str(ipaddress.ip_address(val))
        except Exception:
            _invalid_value(spec, val, "invalid IP address syntax")
    if k == "auth":
        entry, err = parse_auth_value(val)
        if err:
            _invalid_value(spec, val, err)
        return entry
    if k == "header":
        if ":" not in val:
            _invalid_value(spec, val, "invalid header name")
        name, value = val.split(":",1)
        name=name.strip(); value=value.strip()
        if not re.fullmatch(r"[!#$%&'*+\-.^_`|~0-9A-Za-z]+", name or ""):
            _invalid_value(spec, val, "invalid header name")
