def _similar_spec(name):
    # return best candidate spec for unknown long name
    cands = []
    all_names = []
    for s in SPECS:
        all_names.append((s.long, s))
    all_names.append(("help", None)); all_names.append(("version", None))
    import difflib
    for lname, spec in all_names:
        if lname.startswith(name) or name.startswith(lname):
            score = 0.95
        else:
            score = difflib.SequenceMatcher(None, name, lname).ratio()
            # edit distance bonus
            if abs(len(name)-len(lname)) <= 2 and sum(1 for a,b in zip(name,lname) if a!=b) <=2:
                score = max(score, 0.8)
        if score > 0.65:
            cands.append((score, lname, spec))
    if not cands:
        return None
    cands.sort(key=lambda x: -x[0])
    return cands[0]

def _unexpected_arg(token_display, raw_name=None, is_long=False):
    # token_display like --unknown or -x or extra2
    msg = "error: unexpected argument '%s' found\n" % token_display
    suggestion = None
    if is_long and raw_name:
        sim = _similar_spec(raw_name)
        if sim:
            _s, lname, spec = sim
            msg += "\n  tip: a similar argument exists: '--%s'\n" % lname
            if spec is not None:
                usage_disp = spec.display()
            elif lname == "version":
                usage_disp = "--version"
            elif lname == "help":
                usage_disp = "--help"
            else:
                usage_disp = "--%s" % lname
            msg += "\nUsage: %s %s [PATH]\n" % (PROG, usage_disp)
            msg += _err_footer()
            raise ClapExit(msg,2,True)
    # default tip if token looks like a flag
    if token_display.startswith("-"):
        msg += "\n  tip: to pass '%s' as a value, use '-- %s'\n" % (token_display, token_display)
    msg += "\nUsage: %s [OPTIONS] [PATH]\n" % PROG
    msg += _err_footer()
    raise ClapExit(msg,2,True)

