# ---------- QR placeholder (deterministic QR-like SVG) ----------
def qr_svg(url):
    # choose a module count approximating QR versions
    n = len(url.encode())
    if n <= 26:
        size=25
    elif n <= 44:
        size=29
    elif n <= 62:
        size=33
    elif n <= 84:
        size=37
    else:
        size=41
    # deterministic pattern
    import hashlib as _h
    seed = _h.sha256(url.encode()).digest()
    def bit(x,y):
        return (seed[(x*31+y*17) % len(seed)] >> ((x+y) % 8)) & 1
    modules=set()
    def finder(ox,oy):
        for y in range(7):
            for x in range(7):
                border = x in (0,6) or y in (0,6)
                inner = 2<=x<=4 and 2<=y<=4
                if border or inner:
                    modules.add((ox+x,oy+y))
    # background modules from pattern (excluding finder zones)
    zones=[(0,0),(size-7,0),(0,size-7)]
    def in_zone(x,y):
        for ox,oy in zones:
            if ox-1<=x<=ox+7 and oy-1<=y<=oy+7:
                return True
        return False
    for y in range(size):
        for x in range(size):
            if in_zone(x,y): continue
            # timing patterns
            if y==6 or x==6:
                if (x+y)%2==0: modules.add((x,y))
                continue
            if bit(x,y): modules.add((x,y))
    for ox,oy in zones: finder(ox,oy)
    d="".join("M%d,%dh1v1h-1" % (x+1,y+1) for (x,y) in sorted(modules, key=lambda t:(t[1],t[0])))
    return '<svg viewBox="0 0 %d %d" xmlns="http://www.w3.org/2000/svg"><rect width="%dpx" height="%dpx" fill="#ffffff"/><path d="%s" fill="#000000"/></svg>' % (size+2,size+2,size+2,size+2,d)

