    sort_eff, order_eff, ui_active, download, raw = _parse_listing_query(self, query)
    displayed = "/" + "/".join(segs) + ("/" if segs else "/")
    if not displayed.endswith("/"): displayed += "/"
    if displayed == "//": displayed="/"
    # download archive
    if download:
        _send_archive(self, fs_path, download, method); return
    entries=[]
    try:
        it=os.scandir(fs_path)
        with it:
            for entry in it:
                name=entry.name
                if not cfg.hidden and name.startswith("."): continue
                try: is_link=entry.is_symlink()
                except Exception: is_link=False
                if cfg.no_symlinks and is_link: continue
                try: st=entry.stat(follow_symlinks=True)
