    if "application/json" not in ctype.lower():
        body=error_page(cfg,400,"Bad Request","Content type error",show_nav=not bool(cfg.route_prefix))
        self._send(400, body, [("content-type","text/html")]); return
    raw=self.read_body()
    # parse serde-like
    def json_err(msg):
        body=error_page(cfg,400,"Bad Request","Json deserialize error: %s"%msg,show_nav=not bool(cfg.route_prefix))
        self._send(400, body, [("content-type","text/html")])
    try:
        text=raw.decode("utf-8")
    except Exception:
        json_err("expected value at line 1 column 1"); return
    if text.strip()=="":
        json_err("EOF while parsing a value at line 1 column 0"); return
    # serde enum externally tagged: {} gives expected value at line 1 column 2 (observed)
    if text.strip()=="{}":
        json_err("expected value at line 1 column 2"); return
    try:
        obj=json.loads(text)
    except Exception as e:
        json_err("expected value at line 1 column 1"); return
    if not isinstance(obj, dict):
        json_err("expected value at line 1 column 1"); return
    if len(obj)==0:
        json_err("expected value at line 1 column 2"); return
    first_key=list(obj.keys())[0]
    if first_key!="DirSize":
        # column = position of closing quote of key in raw +1
        idx=text.find('"%s"'%first_key)
        col=(idx+len(first_key)+2) if idx>=0 else 1
        json_err("unknown variant `%s`, expected `DirSize` at line 1 column %d"%(first_key,col)); return
    val=obj["DirSize"]
    if not isinstance(val, str):
        typename="integer `%s`"%val if isinstance(val,int) else ("boolean" if isinstance(val,bool) else "value")
        # find column approx end of value
        json_err("invalid type: %s, expected a string at line 1 column %d"%(typename, max(1,len(text.rstrip())-1))); return
    if not cfg.directory_size:
        self._send(200, b"-", [("content-type","text/plain; charset=utf-8")]); return
    # DirSize path is URL path (percent encoded)
    rawp=val
    segs, err = process_raw_segments(rawp if rawp.startswith("/") else "/"+rawp)
    if err:
        code,msg,cause=err
        body=error_page(cfg,400,"Bad Request",msg,cause=cause,show_nav=not bool(cfg.route_prefix))
        self._send(400, body, [("content-type","text/html")]); return
    target=os.path.join(SERVE_ROOT,*segs) if segs else SERVE_ROOT
    if not os.path.exists(target):
        msg="Invalid path"; cause="No such file or directory (os error 2)"
        log_error_chain(msg,cause)
        body=error_page(cfg,400,"Bad Request",msg,cause=cause,show_nav=not bool(cfg.route_prefix))
        self._send(400, body, [("content-type","text/html")]); return
    if not os.path.isdir(target):
        msg="Invalid path"; cause="Not a directory (os error 20)"
        log_error_chain(msg,cause)
        body=error_page(cfg,400,"Bad Request",msg,cause=cause,show_nav=not bool(cfg.route_prefix))
        self._send(400, body, [("content-type","text/html")]); return
    total=0
    for root, dirs, files in os.walk(target, followlinks=True):
        for fn in files:
            try: total+=os.path.getsize(os.path.join(root,fn))
            except Exception: pass
    out = exact_size(total) if cfg.size_display=="exact" else human_size(total)
    self._send(200, out.encode(), [("content-type","text/plain; charset=utf-8")])

