        if internal_raw not in ("/",""):
            self._send(404,b"",[("content-length","0")]); return
    if not os.path.exists(fs_path):
        self._send(404, b"", [("content-length","0")]); return
    def response_for(path_fs, href):
        try: st=os.stat(path_fs)
        except Exception: return ""
        is_dir=os.path.isdir(path_fs)
        creation=datetime.fromtimestamp(st.st_mtime, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        lastmod=format_http_date(st.st_mtime)
        mtime_us=int(st.st_mtime_ns//1000)
        props="<D:creationdate>%s</D:creationdate>"%creation
        if is_dir:
            etag="%x-%x"%(st.st_ino, mtime_us)
            props+="<D:getcontenttype>httpd/unix-directory</D:getcontenttype><D:getetag>%s</D:getetag>"%etag
        else:
            mime=mime_for(os.path.basename(path_fs)).split(";")[0].strip()
            etag="%x-%x-%x"%(st.st_ino, st.st_size, mtime_us)
            props+="<D:getcontentlength>%d</D:getcontentlength><D:getcontenttype>%s</D:getcontenttype><D:getetag>%s</D:getetag>"%(st.st_size, esc(mime), etag)
        props+="<D:getlastmodified>%s</D:getlastmodified><D:lockdiscovery></D:lockdiscovery>"%lastmod
        if is_dir:
            props+="<D:resourcetype><D:collection></D:collection></D:resourcetype>"
        else:
            props+="<D:resourcetype></D:resourcetype>"
        props+="<D:supportedlock></D:supportedlock>"
        return '<D:response><D:href>%s</D:href><D:propstat><D:prop>%s</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat></D:response>'%(esc(href), props)
    displayed_href = (CFG.route_prefix or "") + (internal_raw if internal_raw else "/")
    # ensure dir href ends with slash for collection as in original? request / returns /, /hello.txt returns file href
    body_parts=['<?xml version="1.0" encoding="utf-8"?><D:multistatus xmlns:D="DAV:">']
    body_parts.append(response_for(fs_path, displayed_href))
    if depth=="1" and os.path.isdir(fs_path):
        try:
            with os.scandir(fs_path) as it:
                for entry in it:
                    name=entry.name
                    if not cfg.hidden and name.startswith("."): continue
                    if cfg.no_symlinks and entry.is_symlink(): continue
                    try: st=entry.stat(follow_symlinks=True)
                    except Exception: continue
                    child_href=displayed_href.rstrip("/")+"/"+quote(name,safe="")
                    import stat as _s
                    if _s.S_ISDIR(st.st_mode): child_href+="/"
                    body_parts.append(response_for(entry.path, child_href))
        except Exception:
            pass
    body_parts.append('</D:multistatus>')
    body="".join(body_parts).encode()
    self._send(207, body, [("content-type","application/xml; charset=utf-8"),("cache-control","no-cache"),("pragma","no-cache")], chunked=True)

