# ---------- main ----------
def _workers():
    vals=[]
    try: vals.append(len(os.sched_getaffinity(0)))
    except Exception: pass
    try:
        if os.cpu_count(): vals.append(os.cpu_count())
    except Exception: pass
    try:
        txt=open("/sys/fs/cgroup/cpu.max").read().split()
        if len(txt)>=2 and txt[0]!="max":
            quota=int(txt[0]); period=int(txt[1])
            if period>0: vals.append(max(1,int(math.ceil(quota/period))))
    except Exception: pass
    try:
        q=int(open("/sys/fs/cgroup/cpu/cpu.cfs_quota_us").read()); p=int(open("/sys/fs/cgroup/cpu/cpu.cfs_period_us").read())
        if q>0 and p>0: vals.append(max(1,int(math.ceil(q/p))))
    except Exception: pass
    if vals: return max(1, min(vals))
    return 1

